from functools import wraps
from collections import OrderedDict

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = OrderedDict()
        if maxsize is None:
            maxsize = float('inf')

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, kwargs) if typed else args + tuple(kwargs.items())
            try:
                cache.move_to_end(key)
            except KeyError:
                if len(cache) >= maxsize:
                    cache.popitem(last=False)
            else:
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            return result

        def clear():
            cache.clear()
        wrapper.cache_clear = clear

        def cache_info():
            return {
                'hits': 0,  # hits are not tracked in this simple MRU implementation
                'misses': 0,  # misses are not tracked in this simple MRU implementation
                'maxsize': maxsize,
                'currsize': len(cache),
            }
        wrapper.cache_info = cache_info

        return wrapper

    return decorator

