def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    from collections import OrderedDict

    def flatten_bases(cls):
        bases = [cls]
        for base in cls.__bases__:
            bases.extend(flatten_bases(base))
        return bases

    all_bases = []
    for cls in classes:
        all_bases.extend(flatten_bases(cls))

    # Count occurrences of each base class
    base_count = OrderedDict()
    for base in reversed(all_bases):
        base_count[base] = base_count.get(base, 0) + 1

    # Collect bases that are not the only occurrence of a subclass
    minimal = []
    for base, count in base_count.items():
        if count == 1:
            minimal.append(base)

    return list(OrderedDict.fromkeys(minimal))

