import re
from typing import AnyStr, Union, Iterable, Dict, List, Sequence, Tuple

class SQLParams:
    IN_POSITIONAL = 'positional'
    IN_NAMED = 'named'

class SQLFormatter:
    def __init__(self, in_style: str = SQLParams.IN_NAMED):
        self.in_style = in_style

    def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
    ) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
        out_style_params = []
        param_count = 0

        if self.in_style == SQLParams.IN_NAMED:
            placeholder_re = re.compile(r':([a-zA-Z0-9_]+)')
            for params in many_params:
                new_sql = sql
                new_params = {}
                for name, value in params.items():
                    new_sql = new_sql.replace(f':{name}', f'%({name})s')
                    new_params[name] = value
                out_style_params.append(new_params)
                sql = new_sql
        elif self.in_style == SQLParams.IN_POSITIONAL:
            placeholder_re = re.compile(r'\?')
            for params in many_params:
                new_sql = sql
                new_params = []
                for value in params:
                    new_sql = new_sql.replace('?', f'%s', 1)
                    new_params.append(value)
                out_style_params.append(new_params)
                sql = new_sql

        return sql, out_style_params

