from typing import List

class ExpressionAbsorber:
    def __init__(self, expressions):
        self.expressions = expressions

    def absorb(self, args: List[str]) -> List[str]:
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        new_args = []
        for expr in args:
            if '& (' in expr and '|' in expr and ')' in expr:
                a, rest = expr.split(' & (')
                b, c = rest.split(' | ')
                c = c.rstrip(')')
                if a == b:
                    new_args.append(a)
                elif f'~{a}' == b:
                    new_args.append(f'{a} & {c}')
                else:
                    new_args.append(expr)
            elif '| (' in expr and '&' in expr and ')' in expr:
                a, rest = expr.split(' | (')
                b, c = rest.split(' & ')
                c = c.rstrip(')')
                if a == b:
                    new_args.append(a)
                elif f'~{a}' == b:
                    new_args.append(f'{a} | {c}')
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        return new_args

