import hashlib
from collections import defaultdict

class VersionValidator:
    def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        if not version_dirs:
            raise ValueError("version_dirs should not be empty")

        root_inventory = self.load_inventory(version_dirs[0])
        content_digests = defaultdict(set)

        for digest, path in root_inventory.items():
            content_digests[path].add(digest)

        for version_dir in version_dirs[1:]:
            current_inventory = self.load_inventory(version_dir)
            for digest, path in current_inventory.items():
                if path not in content_digests or digest not in content_digests[path]:
                    raise ValueError(f"Digest {digest} for path {path} in version {version_dir} does not match root inventory")

    def load_inventory(self, version_dir):
        inventory_path = os.path.join(version_dir, 'inventory.txt')
        inventory = {}
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version {version_dir}")

        with open(inventory_path, 'r') as f:
            for line in f:
                digest, path = line.strip().split()
                inventory[digest] = path
        return inventory

