from ruamel.yaml.nodes import ScalarNode, MappingNode

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from collections import defaultdict

    merged_dict = defaultdict(list)

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, MappingNode):
            if key in merged_dict:
                # Merge existing MappingNode with the new one
                existing_mapping = merged_dict[key][1]
                new_mapping = value_node.value
                existing_dict = {item[0].value: item for item in existing_mapping}
                new_dict = {item[0].value: item for item in new_mapping}
                combined_dict = {**existing_dict, **new_dict}
                merged_dict[key][1].value = list(combined_dict.values())
            else:
                # Add new MappingNode
                merged_dict[key] = [key_node, value_node]
        else:
            # For non-MappingNode values, the last one wins
            merged_dict[key] = [key_node, value_node]

    return list(merged_dict.values())

