import re
import sys
import shlex

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Using shlex for POSIX as it handles it well
        return shlex.split(s)
    elif platform == 0:  # Windows/CMD
        # Simple regex for splitting Windows CMD style
        # This is a basic implementation and may not cover all edge cases
        return re.findall(r'[^"\s]+|"[^"]*"', s)
    else:
        raise ValueError("Unsupported platform value. Use 'this', 0 (Windows/CMD), or 1 (POSIX).")

