import subprocess

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''

    def git(args, error_message):
        result = subprocess.run(["git"] + args, capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"{error_message}: {result.stderr}")
        return result.stdout

    ignored_files = git(["check-ignore", "-v", "-n"] + ignored, "Failed to check ignored files")
    ignored_files_list = [line.split()[-1] for line in ignored_files.strip().split('\n') if line]
    sorted_ignored_files = sorted(set(ignored_files_list))
    return ','.join(sorted_ignored_files)

