import logging
import json
import os

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        if not os.path.exists(config_filename):
            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Config file not found: {config_filename}", args=(), exc_info=None))
            continue

        try:
            with open(config_filename, 'r') as file:
                config = json.load(file)
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Error parsing config file: {config_filename}", args=(str(e),), exc_info=None))
            continue

        # Apply overrides
        config.update(overrides)

        # Resolve environment variables if required
        if resolve_env:
            config = {k: v.format(**os.environ) if isinstance(v, str) else v for k, v in config.items()}

        # Validate configuration (dummy validation for example)
        if 'required_key' not in config:
            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Missing required key 'required_key' in config file: {config_filename}", args=(), exc_info=None))
            continue

        config_dict[config_filename] = config

    return config_dict, log_records

