from collections import OrderedDict, Counter

class LFUCache:
    def __init__(self):
        self.cache = OrderedDict()
        self.freq_counter = Counter()
        self.min_freq = 0

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self.cache:
            raise KeyError('Cache is empty')

        # Remove the least frequently used item
        for key, freq in self.freq_counter.items():
            if freq == self.min_freq:
                break

        lru = None
        for k, v in self.cache.items():
            if self.freq_counter[k] == self.min_freq:
                if lru is None or self.cache.move_to_end(k):
                    lru = k

        if lru is not None:
            del self.cache[lru]
            del self.freq_counter[lru]
            return lru, v

        raise KeyError('Cache is empty')

