import json
from xml.etree import ElementTree as ET
from typing import Dict, Any

def parse_diaspora_webfinger(document: str) -> Dict[str, Any]:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            response = {}
            response['subject'] = root.find('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject').text
            links = root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link')
            response['links'] = [
                {link.attrib['rel']: link.attrib['href']} for link in links if 'rel' in link.attrib and 'href' in link.attrib
            ]
            return response
        except ET.ParseError:
            # If both parsing methods fail, return an empty dictionary
            return {}

