class ArgumentValidator:
    def __init__(self, choices_dict):
        """
        Initialize the validator with a dictionary of choices.

        :param choices_dict: A dictionary where keys are argument names and values are lists of valid choices.
        """
        self.choices_dict = choices_dict

    def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments as a dictionary.
        """
        for arg_name, value in args.items():
            if arg_name in self.choices_dict:
                if value not in self.choices_dict[arg_name]:
                    raise ValueError(f"Invalid value for {arg_name}: {value}. Must be one of {self.choices_dict[arg_name]}")

