import sys

class ArgumentValidator:
    def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        if not args:
            raise ValueError("Arguments are required.")

        for arg in args:
            if not isinstance(arg, tuple) or len(arg) != 4:
                raise ValueError("Each argument must be a tuple of the form (value, min, max, name).")

            value, min_val, max_val, name = arg
            if not (min_val <= value <= max_val):
                raise ValueError(f"The value of '{name}' must be between {min_val} and {max_val}, got {value}.")

# Example usage
if __name__ == "__main__":
    validator = ArgumentValidator()
    try:
        validator.validate_min_max_args([(5, 1, 10, 'test_value')])
        print("Validation passed.")
    except ValueError as e:
        print(f"Validation failed: {e}")

